use vstd::prelude::*;

verus! {
    /// An enumeration of possible data types.
    #[verifier(publish)]
    pub enum DataType {
        ScalarInt,
        ScalarFloat,
        ScalarComplex,
        ScalarBool,
        ScalarString,
        ArrayType,
        CompositeType,
        UnknownType,
    }

    /// A pure specification function that characterizes exactly
    /// the scalar variants of `DataType`.
    spec fn is_scalar(dt: DataType) -> bool {
        match dt {
            DataType::ScalarInt => true,
            DataType::ScalarFloat => true,
            DataType::ScalarComplex => true,
            DataType::ScalarBool => true,
            DataType::ScalarString => true,
            DataType::ArrayType => false,
            DataType::CompositeType => false,
            DataType::UnknownType => false,
        }
    }

    /// Returns true exactly when `rep` is one of the scalar types:
    /// ScalarInt, ScalarFloat, ScalarComplex, ScalarBool, or ScalarString.
    fn issctype(rep: DataType) -> (result: bool)
        ensures
            result == is_scalar(rep),
    {
        match rep {
            DataType::ScalarInt => true,
            DataType::ScalarFloat => true,
            DataType::ScalarComplex => true,
            DataType::ScalarBool => true,
            DataType::ScalarString => true,
            DataType::ArrayType => false,
            DataType::CompositeType => false,
            DataType::UnknownType => false,
        }
    }
}

fn main() {
    // Example usage (at runtime):
    let dt1 = DataType::ScalarInt;
    let dt2 = DataType::ArrayType;
    assert!(issctype(dt1) == true);
    assert!(issctype(dt2) == false);
}